-- Minimal pre-migration schema used only by the isolated PostgreSQL tests.
create role anon;
create role authenticated;
create role service_role bypassrls;
create schema auth;
create table auth.users(id uuid primary key,banned_until timestamptz);
create table auth.sessions(id uuid primary key default gen_random_uuid(),user_id uuid);
create table auth.refresh_tokens(user_id text);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.user_id',true),'')::uuid$$;
grant usage on schema auth to authenticated,service_role;
create table public.organizations(id uuid primary key);
create table public.profiles(id uuid primary key,organization_id uuid not null references public.organizations(id),auth_user_id uuid references auth.users(id),membership_status text not null default 'visitor' constraint profiles_membership_status_check check(membership_status in('visitor','returning_visitor','attendee','prospective_member','member','inactive')),date_of_birth date,updated_at timestamptz default now());
create table public.roles(id uuid primary key,organization_id uuid,code text);
create table public.role_permissions(role_id uuid,permission_code text,primary key(role_id,permission_code));
create table public.user_roles(organization_id uuid,user_id uuid,role_id uuid);
create function public.has_permission(org uuid,permission text) returns boolean language sql security definer set search_path='' as $$select exists(select 1 from public.user_roles ur join public.role_permissions rp on rp.role_id=ur.role_id where ur.organization_id=org and ur.user_id=auth.uid() and rp.permission_code=permission)$$;
create function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create table public.events(id uuid primary key,organization_id uuid,title text,starts_at timestamptz,status text,visibility text,registration_opens_at timestamptz,registration_closes_at timestamptz,capacity integer);
create table public.event_registrations(id uuid primary key default gen_random_uuid(),event_id uuid references public.events(id),profile_id uuid references public.profiles(id) on delete set null,guest_name text,guest_email text,guest_phone text,quantity integer not null default 1,status text default 'registered',notes text,created_at timestamptz default now());
alter table public.event_registrations enable row level security;
create policy "event_registrations create" on public.event_registrations for insert to anon,authenticated with check(true);
alter table public.user_roles enable row level security;
create policy "user_roles self read" on public.user_roles for select to authenticated using(user_id=auth.uid());
create table public.notifications(id uuid primary key default gen_random_uuid(),organization_id uuid,user_id uuid references auth.users(id),type text,title text,body text,url text);
create table public.audit_logs(organization_id uuid,actor_id uuid,action text,entity_type text,entity_id text,metadata jsonb);
grant select on public.roles,public.role_permissions,public.user_roles to authenticated;
grant insert on public.event_registrations to anon,authenticated;
grant all on all tables in schema public,auth to service_role;
